<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import{storeToRefs}from'pinia';import FinanceSubnav from'../components/FinanceSubnav.vue';import FinanceScenarioBar from'../components/FinanceScenarioBar.vue';import{useFinanceStore}from'../runtime/finance-store';import type{FinanceEntityStatus,VisibleBankProfile}from'../types';import'./finance-views.css'
const store=useFinanceStore();const{banks,accounts,loading,error,scenario,actor}=storeToRefs(store);const editing=ref<VisibleBankProfile|null|undefined>(undefined),actionError=ref('');const form=reactive({accountId:'',bankName:'',accountName:'',bankAccount:'',branchName:'',accountKind:'corporate'as'corporate'|'personal',status:'enabled'as FinanceEntityStatus});const bankAccounts=computed(()=>accounts.value.filter(r=>r.account.type==='bank'&&(editing.value?.accountId===r.account.id||!banks.value.some(b=>b.accountId===r.account.id))));const money=(v:number)=>`¥${(v/100).toLocaleString('zh-CN',{minimumFractionDigits:2})}`;function open(value:VisibleBankProfile|null){editing.value=value;if(value)Object.assign(form,{accountId:value.accountId,bankName:value.bankName,accountName:value.accountName,bankAccount:value.bankAccount,branchName:value.branchName,accountKind:value.accountKind,status:value.status});else Object.assign(form,{accountId:bankAccounts.value[0]?.account.id??'',bankName:'',accountName:'',bankAccount:'',branchName:'',accountKind:'corporate',status:'enabled'})}async function load(){await Promise.all([store.loadAccounts(),store.loadBanks()])}async function save(){actionError.value='';try{await store.saveBank(crypto.randomUUID(),{...form},editing.value??undefined);editing.value=undefined}catch(e){actionError.value=e instanceof Error?e.message:'保存失败'}}onMounted(load)
</script>
<template><section class="finance-page"><header class="finance-header"><div><h1>银行账户</h1><p>银行资料一对一关联资金账户，不保存第二份余额，也不连接真实银行。</p></div><FinanceScenarioBar :scenario="scenario" :role="actor.role" @scenario="async v=>{await store.setScenario(v);await load()}" @role="async v=>{await store.setRole(v);await load()}"/></header><FinanceSubnav/><div class="finance-toolbar"><strong>银行资料</strong><button class="fin-button primary" :disabled="!bankAccounts.length" @click="open(null)">新增银行资料</button></div><p v-if="actionError||error" class="finance-warning">{{actionError||error}}</p><div v-if="loading" class="finance-state">正在加载银行资料…</div><div v-else-if="!banks.length" class="finance-state"><strong>暂无银行资料</strong><p>请先建立银行类型资金账户，再维护银行资料。</p></div><div v-else class="finance-table-wrap"><table class="finance-table"><thead><tr><th>银行名称</th><th>账户名称</th><th>银行账号</th><th>开户行</th><th>账户类型</th><th class="fin-money">当前余额</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="bank in banks" :key="bank.id"><td>{{bank.bankName}}</td><td>{{bank.accountName}}<small>{{accounts.find(r=>r.account.id===bank.accountId)?.account.name}}</small></td><td>{{bank.bankAccount}}</td><td>{{bank.branchName}}</td><td>{{bank.accountKind==='corporate'?'对公':'对私'}}</td><td class="fin-money">{{money(accounts.find(r=>r.account.id===bank.accountId)?.closingBalanceCents??0)}}</td><td><span class="fin-status" :class="bank.status">{{bank.status==='enabled'?'启用':'停用'}}</span></td><td><button class="fin-button" @click="open(bank)">编辑</button></td></tr></tbody></table></div><div v-if="editing!==undefined" class="finance-dialog"><form class="finance-panel finance-form" @submit.prevent="save"><div class="wide"><h2>{{editing?'编辑':'新增'}}银行资料</h2><p>页面不会将完整账号写入 URL、日志或错误详情。</p></div><label>关联资金账户<select v-model="form.accountId" required><option v-for="row in bankAccounts" :key="row.account.id" :value="row.account.id">{{row.account.name}}</option></select></label><label>银行名称<input v-model.trim="form.bankName" maxlength="100" required></label><label>账户户名<input v-model.trim="form.accountName" maxlength="100" required></label><label>银行账号<input v-model="form.bankAccount" maxlength="64" autocomplete="off" required></label><label>开户行<input v-model.trim="form.branchName" maxlength="120" required></label><label>账户类型<select v-model="form.accountKind"><option value="corporate">对公</option><option value="personal">对私</option></select></label><label>状态<select v-model="form.status"><option value="enabled">启用</option><option value="disabled">停用</option></select></label><div class="finance-actions"><button type="button" class="fin-button" @click="editing=undefined">取消</button><button class="fin-button primary" :disabled="store.saving">保存</button></div></form></div></section></template>
